/**
 * Municipal context from Idescat ("El municipi en xifres"), shipped as a
 * static file generated by scripts/fetch-idescat.mjs. Nothing here calls
 * Idescat at runtime.
 */
import data from "@/data/municipis.json";

export interface Municipality {
  /** Idescat id: INE code plus a check digit, e.g. 082981 for Vic. */
  id: string;
  /** Five-digit INE municipality code, e.g. 08298. */
  ine: string;
  name: string;
  comarca: string;
  population: number | null;
  populationYear: string | null;
  density: number | null;
  pibPerCapita: number | null;
  pibYear: string | null;
  rfdbPerCapita: number | null;
  rfdbYear: string | null;
  /** Índex socioeconòmic territorial, Catalonia = 100. */
  ist: number | null;
  istYear: string | null;
  /** Registered unemployment, annual average. */
  atur: number | null;
  aturYear: string | null;
}

interface MunicipalityFile {
  source: string;
  fetchedAt: string;
  municipalities: Municipality[];
}

const file = data as MunicipalityFile;
const byIne = new Map(file.municipalities.map((m) => [m.ine, m] as const));

export const IDESCAT_SOURCE = file.source;
export const IDESCAT_FETCHED_AT = file.fetchedAt;

/** INE 10-digit local-entity code (as published in the contracts dataset) → municipality. */
export function municipalityFromIne10(code: string | null | undefined): Municipality | null {
  if (!code) return null;
  const digits = code.replace(/\D/g, "");
  if (digits.length < 5) return null;
  return byIne.get(digits.slice(0, 5)) ?? null;
}

export function municipalityByIne(ine: string): Municipality | null {
  return byIne.get(ine) ?? null;
}

export function allMunicipalities(): Municipality[] {
  return file.municipalities;
}
